  /** Right page margin, in rem. Falls back to {@link marginX}. */
  marginRight?: number;
  /** Top (header) page margin, in rem. */
  marginTop?: number;
  /** Bottom (footer) page margin, in rem. */
  marginBottom?: number;
  /** Show brief title / author / date in the running header (print + reading view). */
  runningHeader: boolean;
  /** Show page numbers in the footer of printed/exported output. */
  pageNumbers: boolean;
  /** Show live margin/header/footer guide rules in the editor page. */
  showMarginGuides?: boolean;
  /**
   * Physical sheet the manuscript is set on. Absent on documents written
   * before pagination existed; {@link resolvePageSetup} fills in Letter.
   */
  paper?: PaperSize;
  /** Sheet orientation. Absent on pre-pagination documents — defaults to portrait. */
  orientation?: Orientation;
  /**
   * Whether the editor renders discrete page sheets or one continuous
   * column. Continuous is the pre-pagination behaviour and remains the
   * escape hatch for very long manuscripts.
   */
  pagination?: PaginationMode;
  /**
   * Display unit for the ruler readout only. Margins are *stored* in rem
   * regardless — this changes how they are shown, never how they are saved.
   */
  marginUnit?: MarginUnit;
  /** Opening ornament is presentation only; the manuscript retains its text. */
  openingInitial?: OpeningInitialSettings;
  /** Decorative frame around the manuscript page. */
  pageBorder?: PageBorderStyle;
  /** Number of manuscript columns. */
  columns?: 1 | 2 | 3;
  /** Gap between columns, in rem. */
  columnGap?: number;
}

export function resolveColumns(
  layout: Pick<LayoutSettings, "columns">,
): 1 | 2 | 3 {
  return layout.columns === 2 || layout.columns === 3 ? layout.columns : 1;
}

export function resolveColumnGap(
  layout: Pick<LayoutSettings, "columnGap">,
): number {
  return typeof layout.columnGap === "number" &&
    Number.isFinite(layout.columnGap)
    ? Math.min(3, Math.max(0.75, layout.columnGap))
    : 1.5;
}

/** Older folios and incomplete imported settings keep the house defaults. */
export function resolveOpeningInitial(
  layout: Pick<LayoutSettings, "openingInitial">,
): OpeningInitialSettings {
  const settings = layout.openingInitial;
  return {
    mode:
      settings?.mode === "off" || settings?.mode === "plain"
        ? settings.mode
        : "illuminated",
    collection:
      settings?.collection === "alternate" ? "alternate" : "botanical",
    size:
      settings?.size === "small" || settings?.size === "large"
        ? settings.size
        : "medium",
  };
}

export function resolvePageBorder(
  layout: Pick<LayoutSettings, "pageBorder">,
): PageBorderStyle {
  const border = layout.pageBorder;
  return border === "none" ||
    border === "botanical" ||
    border === "engraved" ||
    border === "illuminated"
    ? border
    : DEFAULT_PAGE_BORDER;
}

