const prompts=[
`Use case: ads-marketing. Asset: exceptionally art-directed photographic landscape website hero for Twyne, a literary writing and revision studio. Output 1536x1024 landscape.
Overhead intimate shared editorial table in a warm quiet writer's room at dusk. Deep dark walnut tabletop and broad matte near-black ink-colored desk blotter form the ENTIRE central 50 percent of frame as quiet uncluttered negative space for cream website typography to be added later. Beautiful cream manuscript sheets with subtle typeset prose and authentic small vermilion editorial correction marks occupy only the far left, lower right and upper corners. Several different fine pens at the outer margins suggest a room of editors working together. One tactile walnut-handled brass rubber stamp near the lower left margin. Elegant restrained lived-in composition, not generic stock flatlay, no coffee or flowers. Soft warm directional window light across fibrous paper edges, rich ink blacks, natural walnut, ivory and restrained vermilion. Real material detail, cinematic editorial photography, subtle film grain. Empty center is dark and genuinely spacious, objects never cross central copy-safe area. No people, no hands, no logos, no headlines, no website mockup, no UI, no watermark.`,
`Use case: ads-marketing. Asset: sophisticated macro photographic landscape website hero for Twyne, an editorial writing and revision studio. Output 1536x1024 landscape.
Striking extreme-close photographic still life: a slender vermilion red editorial pen with exposed fine metal nib resting diagonally across the OUTER RIGHT edge of an ivory manuscript sheet, with convincing red proofreading strokes, deletion mark, caret and underline beside small black typeset prose. Paper and pen occupy rightmost quarter and lower-right edge only. A second softly lit layered cream page corner enters at far upper-left. The central 50 percent and left-middle is open rich almost-black matte ink-colored desktop with subtle tactile grain, absolutely clear for cream hero text to be added later. Dimensional layered paper shadows and warm raking light make the cream edges luminous against darkness. Art-directed asymmetric literary luxury, quiet and tactile, real fine fiber paper and restrained red ink, very high-quality macro photography, shallow depth of field at extreme margins but central area softly uniform. Clearly writing and revision, not a stationery catalogue. No readable headlines, no logos, no UI, no watermark, no hands, no flowers, no decorative border. Do not put text or an object in the central copy-safe area.`
];
await Promise.all(prompts.map(async(prompt,i)=>{
const result=await tools.image_gen__imagegen({prompt,transparent_background:false});
const path=result.output_hint?.match(/as (\/[^\n]+?\.png) by default/)?.[1];
const entry={id:`option-0${i+1}`,title:i===0?"The editorial table":"The red pen",generatedWith:"built-in image_gen",source:path,prompt};
await tools.apply_patch(`*** Begin Patch\n*** Add File: /home/diogenes/Projects/twyne/public/assets/landing/options-2026-09/option-0${i+1}.json\n+${JSON.stringify(entry,null,2).split("\n").join("\n+")}\n*** End Patch`);
text({id:entry.id,path});
}));

