const fs=require('fs'),crypto=require('crypto'),sharp=require('/home/diogenes/Projects/twyne/node_modules/sharp');
const root='/home/diogenes/Projects/twyne/public/assets/landing/options-2026-09';
(async()=>{for(const n of ['01','02']){
 const file=`${root}/option-${n}.json`,entry=JSON.parse(fs.readFileSync(file));
 entry.sourceSha256=crypto.createHash('sha256').update(fs.readFileSync(entry.source)).digest('hex');entry.outputs=[];
 for(const width of [1536,768]) {const filename=`option-${n}-${width}.avif`;await sharp(entry.source).resize(width).avif({quality:70,effort:6,chromaSubsampling:'4:4:4'}).toFile(`${root}/${filename}`);const meta=await sharp(`${root}/${filename}`).metadata();entry.outputs.push({filename,width:meta.width,height:meta.height,bytes:fs.statSync(`${root}/${filename}`).size,quality:70,effort:6,chromaSubsampling:'4:4:4'});}
 fs.writeFileSync(file,JSON.stringify(entry,null,2)+'\n');console.log(JSON.stringify({id:entry.id,outputs:entry.outputs}));
 await sharp(`${root}/option-${n}-768.avif`).png().toFile(`/tmp/twyne-hero-option-${n}.png`);
}})();
JS","max_output_tokens":2000,"yield_time_ms":1000}));

